"""Contact sheet for substitute teachers."""

from rosterkit.errors import ProjectError


def _check(students):
    if not students:
        raise ProjectError("No students given")
    for student in students:
        if not student.email:
            raise ProjectError(
                f"No email for {student.display_name}"
            )


def _line(values, widths):
    cells = (v.ljust(w) for v, w in zip(values, widths))
    return "  ".join(cells).rstrip()


def contact_rows(students):
    """Text rows of name, section, email sorted by name."""
    _check(students)
    ordered = sorted(students, key=lambda s: s.display_name)
    cols = [(s.display_name, s.section, s.email)
            for s in ordered]
    widths = [max(map(len, c)) for c in zip(*cols)]
    return [_line(c, widths) for c in cols]

